'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var EPS = require( '@stdlib/constants/float64/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var dgetrf = require( './../lib/ndarray.js' );


// FIXTURES //

var POSITIVE_STRIDES_NO_OFFSET_1 = require( './fixtures/positive_stride_no_offset_1.json' ); // eslint-disable-line id-length
var POSITIVE_STRIDES_NO_OFFSET_2 = require( './fixtures/positive_stride_no_offset_2.json' ); // eslint-disable-line id-length
var LARGE_POSITIVE_STRIDE_1 = require( './fixtures/large_positive_stride_1.json' );
var LARGE_POSITIVE_STRIDE_2 = require( './fixtures/large_positive_stride_2.json' );
var NEGATIVE_STRIDES = require( './fixtures/negative_strides.json' );
var MIXED_STRIDES = require( './fixtures/mixed_strided.json' );
var POSITIVE_STRIDES_OFFSET_1 = require( './fixtures/positive_stride_offset_1.json' );
var POSITIVE_STRIDES_OFFSET_2 = require( './fixtures/positive_stride_offset_2.json' );


// FUNCTIONS //

function isApprox( t, actual, expected ) {
	var delta;
	var tol;
	var i;

	t.strictEqual( actual.length, expected.length, 'returns expected value' );
	for ( i = 0; i < expected.length; i++ ) {
		if ( actual[ i ] === expected[ i ] ) {
			t.strictEqual( actual[ i ], expected[ i ], 'returns expected value' );
		} else {
			delta = abs( actual[ i ] - expected[ i ] );
			tol = 2.0 * EPS * abs( expected[ i ] );
			t.ok( delta <= tol, 'within tolerance' );
		}
	}
}

function testFixture( t, data ) {
	var A = new Float64Array( data.A );
	var IPIV = new Int32Array( data.IPIV );
	var info = dgetrf( data.M, data.N, A, data.strideA1, data.strideA2, data.offsetA, IPIV, data.strideIPIV, data.offsetIPIV ); // eslint-disable-line max-len

	t.strictEqual( info, data.expectedInfo, 'returns expected status code' );
	t.deepEqual( IPIV, new Int32Array( data.expectedIPIV ), 'returns expected pivot indices' );
	isApprox( t, A, new Float64Array( data.expectedA ) );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dgetrf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 9', function test( t ) {
	t.strictEqual( dgetrf.length, 9, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided invalid dimensions', function test( t ) {
	var A = new Float64Array( 4 );
	var IPIV = new Int32Array( 2 );

	t.throws( function badRows() {
		dgetrf( -1, 2, A, 1, 2, 0, IPIV, 1, 0 );
	}, RangeError, 'throws for a negative row count' );
	t.throws( function badColumns() {
		dgetrf( 2, -1, A, 1, 2, 0, IPIV, 1, 0 );
	}, RangeError, 'throws for a negative column count' );
	t.end();
});

tape( 'the function computes factorizations with positive strides', function test( t ) {
	testFixture( t, POSITIVE_STRIDES_NO_OFFSET_1 );
	testFixture( t, POSITIVE_STRIDES_NO_OFFSET_2 );
	testFixture( t, LARGE_POSITIVE_STRIDE_1 );
	testFixture( t, LARGE_POSITIVE_STRIDE_2 );
	t.end();
});

tape( 'the function supports index offsets', function test( t ) {
	testFixture( t, POSITIVE_STRIDES_OFFSET_1 );
	testFixture( t, POSITIVE_STRIDES_OFFSET_2 );
	t.end();
});

tape( 'the function supports negative and mixed strides', function test( t ) {
	testFixture( t, NEGATIVE_STRIDES );
	testFixture( t, MIXED_STRIDES );
	t.end();
});
